import random

def check_condition(grid, N):
    for i in range(N - 1):
        for j in range(N - 1):
            colors = {grid[i][j], grid[i+1][j], grid[i][j+1], grid[i+1][j+1]}
            if len(colors) == 4:
                return False
    return True

def find_max_colors(N, attempts=1000):
    max_colors = 0
    for _ in range(attempts):
        grid = [[0]*N for _ in range(N)]
        current_colors = 0
        cells = [(i, j) for i in range(N) for j in range(N)]
        random.shuffle(cells)

        for r, c in cells:
            grid[r][c] = current_colors + 1
            possible = True
            for dr in [-1, 0]:
                for dc in [-1, 0]:
                    i, j = r + dr, c + dc
                    if 0 <= i < N-1 and 0 <= j < N-1:
                        subgrid = [grid[i][j], grid[i+1][j], grid[i][j+1], grid[i+1][j+1]]
                        if all(x != 0 for x in subgrid):
                            if len(set(subgrid)) == 4:
                                possible = False
                                break
                if not possible: break

            if possible:
                current_colors += 1
            else:
                found_color = False
                # Try all existing colors to see if any satisfy the condition
                # For faster searching, let's try the colors in the subgrids first.
                relevant_colors = set()
                for dr in [-1, 0]:
                    for dc in [-1, 0]:
                        i, j = r + dr, c + dc
                        if 0 <= i < N-1 and 0 <= j < N-1:
                            for rr in [i, i+1]:
                                for cc in [j, j+1]:
                                    if grid[rr][cc] != 0:
                                        relevant_colors.add(grid[rr][cc])

                for color in relevant_colors:
                    grid[r][c] = color
                    possible = True
                    for dr in [-1, 0]:
                        for dc in [-1, 0]:
                            i, j = r + dr, c + dc
                            if 0 <= i < N-1 and 0 <= j < N-1:
                                subgrid = [grid[i][j], grid[i+1][j], grid[i][j+1], grid[i+1][j+1]]
                                if all(x != 0 for x in subgrid):
                                    if len(set(subgrid)) == 4:
                                        possible = False
                                        break
                        if not possible: break
                    if possible:
                        found_color = True
                        break

                if not found_color:
                    grid[r][c] = 0
                    break
        else:
            max_colors = max(max_colors, current_colors)
    return max_colors

for n in range(2, 6):
    print(f"N={n}, max_colors={find_max_colors(n, 2000)}")
